import type { Db } from 'mongodb';
type Refusal = { ok: false; status: number; code: string; error: string };
export type QuizContext = { ok: true; member: { userId: string; role: string; email: string }; staff: boolean; lesson: any; course: any; courseId: string; lessonId: string; quiz: any };
export const COLLECTIONS: { attempts: string; counters: string; scores: string };
export function counterId(userId: string, lessonId: string): string;
export function loadQuizContext(db: Db, input: { userId: string; lessonId: string; withAnswerKey?: boolean }): Promise<QuizContext | Refusal>;
export function startAttempt(db: Db, ctx: QuizContext, options?: { now?: Date; random?: () => number }): Promise<{ ok: true; attempt: any; resumed: boolean } | Refusal | { ok: false; status: number; code: string; error: string }>;
export function readAttempt(db: Db, ctx: QuizContext, attemptId: string, options?: { now?: Date }): Promise<{ ok: true; attempt: any } | Refusal>;
export function saveAnswer(db: Db, ctx: QuizContext, attemptId: string, body: any, options?: { now?: Date }): Promise<{ ok: true; attempt: any } | Refusal>;
export function submitAttempt(db: Db, ctx: QuizContext, attemptId: string, body: any, options?: { now?: Date }): Promise<{ ok: true; attempt: any; alreadyFinal?: boolean; expired?: boolean } | Refusal>;
export function reviewFor(db: Db, ctx: QuizContext, attempt: any): Promise<boolean>;
export function attemptOverview(db: Db, ctx: QuizContext, options?: { now?: Date }): Promise<Record<string, unknown>>;
export function quizResults(db: Db, ctx: QuizContext, options?: { page?: number; limit?: number; now?: Date }): Promise<Record<string, unknown>>;
export function attemptForStaff(db: Db, ctx: QuizContext, attemptId: string): Promise<{ ok: true; attempt: any } | Refusal>;
export function assessmentHistory(db: Db, input: { userId: string; page?: number; limit?: number }): Promise<Record<string, unknown>>;
export function closeLessonAttempts(db: Db, lessonId: string, options?: { now?: Date }): Promise<{ cancelled: number }>;
export function reconcileAttempt(db: Db, attempt: any, now?: Date): Promise<any>;
export function sweepAttempts(db: Db, options?: { apply?: boolean; now?: Date; limit?: number }): Promise<{ pending: number; overdue: number; reconciled: number; expired: number; failed: number }>;
export function finalizeAttempt(db: Db, attempt: any, input: { status: string; answers: any; now: Date }): Promise<any>;
export function checkAnswers(attempt: any, input: unknown): { ok: true; answers: Record<string, number> } | Refusal;
